/* BV-GARDEN · persistence + reward audio. Independently preserves the existing lessons and map. */
'use strict';
(() => {
  const POSITION_KEY='bv-garden-explorer-position-v1';
  const SOUND_KEY='bv-garden-sound-enabled-v1';
  const soundSources={
    stella:'data:audio/mpeg;base64,',
    fail:'data:audio/mpeg;base64,'
  };
  const playerSounds={};
  let soundEnabled=true;
  try {soundEnabled=localStorage.getItem(SOUND_KEY)!=='false';}catch(_){/*private mode*/}
  function soundFor(kind){
    if(!playerSounds[kind]){const a=new Audio(soundSources[kind]);a.preload='auto';playerSounds[kind]=a;}
    return playerSounds[kind];
  }
  function playSound(kind){
    if(!soundEnabled)return;
    try {const audio=soundFor(kind);audio.pause();audio.currentTime=0;const p=audio.play();if(p&&typeof p.catch==='function')p.catch(()=>{});}catch(_){/*audio might be blocked on some browsers*/}
  }
  const soundButton=document.getElementById('soundless');
  function renderSoundButton(){if(!soundButton)return;soundButton.textContent=soundEnabled?'♪ mute sounds':'♪ enable sounds';soundButton.setAttribute('aria-pressed',String(!soundEnabled));soundButton.setAttribute('aria-label',soundEnabled?'Mute game sound effects':'Enable game sound effects');}
  if(soundButton){soundButton.addEventListener('click',()=>{
    soundEnabled=!soundEnabled;
    try{localStorage.setItem(SOUND_KEY,String(soundEnabled));}catch(_){}
    if(!soundEnabled)Object.values(playerSounds).forEach(a=>{try{a.pause();a.currentTime=0;}catch(_){}});
    renderSoundButton();
  });renderSoundButton();}
  // The existing quest engine already atomically saves stars, bolts, unused questions,
  // and active quiz choices. Persist the location and camera *in addition*.
  function storeExplorer(){
    try{
      const x=Number(state.player.x),y=Number(state.player.y);
      if(!Number.isFinite(x)||!Number.isFinite(y))return;
      localStorage.setItem(POSITION_KEY,JSON.stringify({version:1,epoch:quest.epoch||0,
        player:{x,y},pan:{x:state.explorePan?.x||0,y:state.explorePan?.y||0},
        selection:Number.isInteger(state.selection)?state.selection:null,savedAt:Date.now()}));
    }catch(_){/*storage unavailable*/}
  }
  let loaded=null;
  try {loaded=JSON.parse(localStorage.getItem(POSITION_KEY)||'null');}catch(_){}
  if(loaded&&loaded.version===1&&loaded.epoch===(quest.epoch||0)&&loaded.player&&
     Number.isFinite(loaded.player.x)&&Number.isFinite(loaded.player.y)){
    state.player={x:Math.max(0,Math.min(NX-1,loaded.player.x)),y:Math.max(0,Math.min(NY-1,loaded.player.y))};
    state.travel=null;
    const px=Number(loaded.pan?.x),py=Number(loaded.pan?.y);
    state.explorePan={x:Number.isFinite(px)?Math.max(-1800,Math.min(1800,px)):0,
      y:Number.isFinite(py)?Math.max(-1100,Math.min(1100,py)):0};
    state.cam.x=W*.5-rawIso(state.player.x,state.player.y).x+state.explorePan.x;
    state.cam.y=H*.58-rawIso(state.player.x,state.player.y).y+state.explorePan.y;
  }
  // Resume an unfinished quiz before reopening any other journal chapter.
  if(quest.active){openChapter(quest.active.kind==='exam'?20:quest.active.level);}
  else if(loaded&&loaded.epoch===(quest.epoch||0)&&Number.isInteger(loaded.selection)&&loaded.selection>=0&&loaded.selection<=20){openChapter(loaded.selection);}
  // Audio plays exclusively when a *new* Stella is earned after all four chapter questions.
  const originalToast=showRewardToast;
  showRewardToast=function(kind,message){originalToast(kind,message);if(kind==='stella'&&message==='Stella Star earned!')playSound('stella');};
  // The 10th incorrect answer invokes the existing restart procedure; play the uploaded
  // trumpet once and keep the explicit notice visible after the new run begins.
  const originalRestart=restartForBolts;
  restartForBolts=function(){originalRestart();state.explorePan={x:0,y:0};storeExplorer();showRewardToast('tonitrus','10 Tonitrus Bolts · adventure restarted at Chapter 01');playSound('fail');};
  // Advanced five-Bolt reset: reuse the existing sound without resetting the main journey.
  document.addEventListener('bv-advanced-bolt-reset',()=>playSound('fail'));
  // Keep the last explored tile/pan even after sudden tab closure or device sleep.
  const flush=()=>storeExplorer();
  document.addEventListener('pointerup',()=>setTimeout(flush,0));
  document.addEventListener('keyup',flush);
  document.addEventListener('click',()=>setTimeout(flush,0));
  document.addEventListener('visibilitychange',()=>{if(document.hidden)flush();});
  window.addEventListener('pagehide',flush);
  window.addEventListener('beforeunload',flush);
  setInterval(flush,1100);
  if(quest.bolts>=10)restartForBolts(); // migrate saves already at the new limit
  storeExplorer();
})();